contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        require(recipient != address(0), "zero recipient");

        uint beforeContractBalance = address(c).balance;
        uint beforeRecipientBalance = address(recipient).balance;

        bool reverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterContractBalance = address(c).balance;
        uint afterRecipientBalance = address(recipient).balance;

        bool directReverted;
        c.withdrawReward(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            directReverted = true;
        } else {
            directReverted = false;
        }

        uint finalContractBalance = address(c).balance;
        uint finalRecipientBalance = address(recipient).balance;

        assert(
            (reverted && afterContractBalance == beforeContractBalance) ||
            (!reverted && beforeContractBalance >= 100 && afterContractBalance + 100 == beforeContractBalance && finalContractBalance == afterContractBalance && finalRecipientBalance == afterRecipientBalance)
        );
    }

    receive() external payable {}
}

